async function main() {
  console.log(`Starting seed of ${players.length} real players...`);
  
  let inserted = 0;
  let skipped = 0;
  
  try {
    for (const p of players) {
      // Check if exists
      const [rows] = await pool.query('SELECT player_id FROM players WHERE enrollment_number = ?', [p.enrollment_number]);
      
      if (rows.length > 0) {
        skipped++;
        continue;
      }
      
      // Insert
      const keys = Object.keys(p);
      const values = Object.values(p);
      
      const placeholders = keys.map(() => '?').join(', ');
      const query = `INSERT INTO players (${keys.join(', ')}) VALUES (${placeholders})`;
      
      await pool.query(query, values);
      inserted++;
      
      if (inserted % 50 === 0) {
        console.log(`Inserted ${inserted} players...`);
      }
    }
    
    console.log(`Completed player insertion. Inserted: ${inserted}, Skipped: ${skipped}`);
    
    // Recalculate rankings for all base_price_auto = 1
    console.log('Recalculating rankings and base prices...');
    await recalculateRankings();
    console.log('Done recalculating rankings.');
    
  } catch (err) {
    console.error('Error during seed:', err);
  } finally {
    pool.end();
  }
}

if (require.main === module) {
  main().then(() => console.log('Seeding process finished.'));
}

module.exports = { main };
